//@version=6
// =============================================================================
// H-005 · Liquidity sweep fade  —  board score 4.0/10  —  REJECTED
// prop_lab · https://github.com/KristijonasSim/prop_lab
//
// DO NOT TRADE THIS. It is here so the board is complete and so the rejection
// can be re-checked by hand, not because it is a candidate.
//
// WHY IT WAS REJECTED: 541,474 configurations across 12 markets and 5
// timeframes. The real data cleared PF 1.20 on 1,702 of them. The paired-shuffle
// null cleared it on 19,062 — ELEVEN TIMES MORE — and the null's best config
// (3.858) beat the real best (1.929). Only 2 of 57 market x timeframe pairs beat
// their own null. A sweep-and-revert rule is simply EASIER to satisfy on
// shuffled data, because a permuted series reverts around its extremes more
// readily than a real trending one. Anything that looks good here is that
// artefact, not an edge.
//
// Mechanism as originally stated: price takes out an N-bar extreme, trapping
// the stops resting beyond it, then closes back inside the range on the same
// bar. The counterparty is whoever just got filled at the worst price of the
// move. Fade it.
// =============================================================================
strategy("H-005 Liquidity sweep fade · prop_lab [REJECTED]", overlay=true,
     initial_capital=10000, default_qty_type=strategy.percent_of_equity,
     default_qty_value=100, commission_type=strategy.commission.percent,
     commission_value=0.05, margin_long=100, margin_short=100, pyramiding=0)

lookback  = input.int(20,    "Range lookback (bars)",        minval=5)
pierceATR = input.float(0.1, "Pierce depth (ATR)",           minval=0.0, step=0.05)
needWick  = input.bool(true, "Require close back inside the range")
minRngATR = input.float(1.0, "Minimum range (ATR)",          minval=0.0, step=0.5)
stopK     = input.float(1.0, "Stop beyond the swept extreme (ATR)", minval=0.1, step=0.5)
rrIn      = input.float(0.0, "Target (R multiple, 0 = fade back to the far side)", minval=0.0, step=0.5)
atrLen    = input.int(14,    "ATR length",                   minval=2)

a  = ta.atr(atrLen)
hi = ta.highest(high[1], lookback)
lo = ta.lowest(low[1],   lookback)
rng = hi - lo
rangeOK = rng >= minRngATR * a

// swept the highs -> trapped longs above -> fade short, and the mirror
sweptHigh = high > hi + pierceATR * a and (not needWick or close < hi)
sweptLow  = low  < lo - pierceATR * a and (not needWick or close > lo)

canTrade = rangeOK and a > 0 and barstate.isconfirmed

if canTrade and sweptLow and strategy.position_size <= 0
    st = low - stopK * a
    strategy.entry("L", strategy.long)
    if rrIn > 0
        strategy.exit("L x", "L", stop=st, limit=close + rrIn * (close - st))
    else
        strategy.exit("L x", "L", stop=st, limit=hi)

if canTrade and sweptHigh and strategy.position_size >= 0
    st = high + stopK * a
    strategy.entry("S", strategy.short)
    if rrIn > 0
        strategy.exit("S x", "S", stop=st, limit=close - rrIn * (st - close))
    else
        strategy.exit("S x", "S", stop=st, limit=lo)

plot(hi, "Range high", color.new(color.gray, 30))
plot(lo, "Range low",  color.new(color.gray, 30))
plotshape(canTrade and sweptHigh, "Sweep high", shape.triangledown, location.abovebar, color.new(color.red, 0), size=size.tiny)
plotshape(canTrade and sweptLow,  "Sweep low",  shape.triangleup,   location.belowbar, color.new(color.green, 0), size=size.tiny)

//@version=6
// =============================================================================
// H-007 · Cross-sectional crypto ranking  —  board score 2.9/10  —  REJECTED
// prop_lab · https://github.com/KristijonasSim/prop_lab
//
// DO NOT TRADE THIS. Kept because HOW it failed is the useful part.
//
// WHY IT WAS REJECTED — and this one is different from the others. The ranking
// CARRIES REAL INFORMATION: before costs, 95.0% of the 360 real configurations
// beat PF 1.0 against the paired null's 59.4% (median 1.096 vs 1.009). That is a
// cleaner separation from the null than H-003 or H-005 ever managed.
//
// It still fails, because the edge is worth about 10% on profit factor and a
// 14bps round trip is worth more than that. Median PF by cost: 1.096 (0x) ->
// 0.825 (1x) -> 0.618 (2x). Every configuration that cleared the gate at 2x was
// a 1-day bar held 7 days, 0.14 trades/day, with 400-875 days to target against
// H-002's 25. Walk-forward: 1.168, and 1.063 at 2x — under the gate, with the
// best of five null seeds at 1.065 BEATING it.
//
// COST-LIMITED, NOT SIGNAL-LIMITED. That matters: a signal that loses to its
// null is dead, but one that loses to the spread gets better with a wider
// universe, because cross-sectional dispersion grows with the number of names
// ranked while the cost per trade does not. The published versions rank 500 to
// 7,000 names. This ranks five, which is why it is closer to a coin-flip on
// dispersion than to the real mechanic.
//
// Add symbols in the inputs to test that directly — it is the one open route.
// =============================================================================
strategy("H-007 Cross-sectional ranking · prop_lab [REJECTED]", overlay=false,
     initial_capital=10000, default_qty_type=strategy.percent_of_equity,
     default_qty_value=100, commission_type=strategy.commission.percent,
     commission_value=0.05, margin_long=100, margin_short=100, pyramiding=0)

sig   = input.string("momentum", "Ranking signal", options=["momentum","relative volume"],
     tooltip="momentum = L-bar log return. relative volume = volume over its own " +
             "rolling median, which is the signal the published equity version uses.")
L     = input.int(6,  "Lookback (bars)", minval=1)
mode  = input.string("spread", "Book", options=["spread","long only"],
     tooltip="spread = long the top name, short the bottom. long only = top name only.")
holdB = input.int(7,  "Hold (bars)", minval=1,
     tooltip="Everything that survived cost in the study was a 7-day hold on 1d bars.")

s1 = input.symbol("BINANCE:BTCUSDT", "Coin 1")
s2 = input.symbol("BINANCE:ETHUSDT", "Coin 2")
s3 = input.symbol("BINANCE:SOLUSDT", "Coin 3")
s4 = input.symbol("BINANCE:BNBUSDT", "Coin 4")
s5 = input.symbol("BINANCE:XRPUSDT", "Coin 5")

score(sym) =>
    [c, vv] = request.security(sym, timeframe.period, [close, volume], lookahead=barmerge.lookahead_off)
    m  = math.log(c / c[L])
    md = ta.median(vv, L)
    sig == "momentum" ? m : (md > 0 ? vv / md : na)

r1 = score(s1)
r2 = score(s2)
r3 = score(s3)
r4 = score(s4)
r5 = score(s5)

// rank the current chart symbol against the five, on the same measure
own    = sig == "momentum" ? math.log(close / close[L]) :
         (ta.median(volume, L) > 0 ? volume / ta.median(volume, L) : na)
best   = math.max(r1, r2, r3, r4, r5)
worst  = math.min(r1, r2, r3, r4, r5)
isTop  = not na(own) and not na(best)  and own >= best
isBot  = not na(own) and not na(worst) and own <= worst

ready = barstate.isconfirmed and not na(own)
if ready and isTop and strategy.position_size <= 0
    strategy.entry("L", strategy.long)
if ready and isBot and mode == "spread" and strategy.position_size >= 0
    strategy.entry("S", strategy.short)

held = ta.barssince(strategy.position_size[1] == 0 and strategy.position_size != 0)
if strategy.position_size != 0 and held >= holdB
    strategy.close_all("hold")

plot(own, "This symbol", color.new(color.orange, 0), 2)
plot(best,  "Best of set",  color.new(color.green, 40))
plot(worst, "Worst of set", color.new(color.red, 40))
hline(0, "", color.new(color.gray, 60))

//@version=6
// =============================================================================
// H-008 · Beta-residual reversion  —  board score 2.1/10  —  REJECTED
// prop_lab · https://github.com/KristijonasSim/prop_lab
//
// DO NOT TRADE THIS. It is the most decisively rejected idea on the board.
//
// WHY IT WAS REJECTED: 1,152 configurations. ZERO cleared PF 1.20 at 2x cost,
// and the paired-shuffle null beat the real data on EVERY cut — 55.4% of null
// configs profitable before costs against the real 51.6%, best PF at 2x 1.496
// against 0.940. This is the H-005 trap again: a fade rule is EASIER to satisfy
// on shuffled data, because permuted series revert around their extremes more
// readily than real trending ones.
//
// THE DECISIVE DIAGNOSTIC IS THE Z-RESPONSE, AND IT IS FLAT. Profit factor
// before any costs, by entry threshold: 1.5σ -> 1.000, 2.0σ -> 0.997,
// 2.5σ -> 1.006, 3.0σ -> 1.013. A three-sigma residual reverts NO HARDER than a
// 1.5-sigma one. The size of the deviation carries no information about what
// happens next. Nothing here is cost-limited; there is no edge to protect.
//
// Every walk-forward fold also selected a config whose TRAIN profit factor was
// already below 1.0 — the selector could not find a winner even in sample.
//
// Watch the histogram against the threshold bands as you raise the z input: if
// a mechanism were there, the deeper bars would be followed by sharper snapbacks.
// They are not. That is the whole result, visible on a chart.
//
// Mechanism as originally stated: BTC is the liquidity centre and alts trade as
// a beta to it. A large short-horizon residual should be a liquidity event — a
// market order sweeping a thin book — not information, so it should revert once
// makers refill. Run this on ETH, SOL, BNB or XRP.
// =============================================================================
strategy("H-008 Beta-residual reversion · prop_lab [REJECTED]", overlay=false,
     initial_capital=10000, default_qty_type=strategy.percent_of_equity,
     default_qty_value=100, commission_type=strategy.commission.percent,
     commission_value=0.05, margin_long=100, margin_short=100, pyramiding=0)

factorSym = input.symbol("BINANCE:BTCUSDT", "Market factor")
betaWin   = input.int(100, "Beta window (bars)",     minval=10)
L         = input.int(16,  "Residual lookback (bars)", minval=1)
zWin      = input.int(100, "Z-score window (bars)",  minval=20)
zThr      = input.float(3.0, "Entry threshold (σ)",  minval=0.5, step=0.5)
holdB     = input.int(2,   "Hold (bars)",            minval=1)

fc = request.security(factorSym, timeframe.period, close, lookahead=barmerge.lookahead_off)

rc = math.log(close / close[1])
rb = math.log(fc / fc[1])

// rolling beta of this coin on the factor, history up to and including this bar
cv   = ta.cov(rc, rb, betaWin)
vr   = ta.variance(rb, betaWin)
beta = vr > 0 ? math.max(math.min(cv / vr, 5.0), -5.0) : na

// residual move over the last L bars, and its z-score
Lc    = math.log(close / close[L])
Lb    = math.log(fc / fc[L])
resid = Lc - beta * Lb
sd    = ta.stdev(resid, zWin)
z     = sd > 0 ? (resid - ta.sma(resid, zWin)) / sd : na

ready = barstate.isconfirmed and not na(z) and not na(beta)
// fade the residual
if ready and z <= -zThr and strategy.position_size <= 0
    strategy.entry("L", strategy.long)
if ready and z >= zThr and strategy.position_size >= 0
    strategy.entry("S", strategy.short)

held = ta.barssince(strategy.position_size[1] == 0 and strategy.position_size != 0)
if strategy.position_size != 0 and held >= holdB
    strategy.close_all("hold")

plot(z, "Residual z", color.new(color.orange, 0), 2, plot.style_histogram)
hline(0, "", color.new(color.gray, 60))
hline(zThr,  "Short", color.new(color.red, 30),   hline.style_dashed)
hline(-zThr, "Long",  color.new(color.green, 30), hline.style_dashed)
